// ============================================================
//  showcase3d.js — Interactive 3D Showcase (Student ID & Wallet)
//  Built with Three.js Core UMD for 100% offline & file:// compatibility
// ============================================================

const ID_CARD_BASE64 = "data:image/jpeg;base64,";

// ------------------------------------------------------------
//  SHARED GEOMETRY & UTILITIES
// ------------------------------------------------------------
function createRoundedRectShape(w, h, r) {
  const shape = new THREE.Shape();
  const x = -w / 2;
  const y = -h / 2;
  const radius = Math.min(r, w / 2, h / 2);
  shape.moveTo(x + radius, y);
  shape.lineTo(x + w - radius, y);
  shape.quadraticCurveTo(x + w, y, x + w, y + radius);
  shape.lineTo(x + w, y + h - radius);
  shape.quadraticCurveTo(x + w, y + h, x + w - radius, y + h);
  shape.lineTo(x + radius, y + h);
  shape.quadraticCurveTo(x, y + h, x, y + h - radius);
  shape.lineTo(x, y + radius);
  shape.quadraticCurveTo(x, y, x + radius, y);
  return shape;
}

function createRoundedBox(w, h, d, r, bevel) {
  const shape = createRoundedRectShape(w, h, r);
  const geom = new THREE.ExtrudeGeometry(shape, {
    depth: d,
    bevelEnabled: !!bevel,
    bevelSegments: 3,
    steps: 1,
    bevelSize: bevel || 0.01,
    bevelThickness: bevel || 0.01
  });
  geom.center();
  return geom;
}

function createShadowTexture() {
  const canvas = document.createElement('canvas');
  canvas.width = 256;
  canvas.height = 256;
  const ctx = canvas.getContext('2d');
  const grad = ctx.createRadialGradient(128, 128, 8, 128, 128, 120);
  grad.addColorStop(0, 'rgba(42, 75, 48, 0.42)');
  grad.addColorStop(0.35, 'rgba(42, 75, 48, 0.20)');
  grad.addColorStop(0.70, 'rgba(42, 75, 48, 0.06)');
  grad.addColorStop(1, 'rgba(42, 75, 48, 0)');
  ctx.fillStyle = grad;
  ctx.beginPath();
  ctx.arc(128, 128, 120, 0, Math.PI * 2);
  ctx.fill();
  return new THREE.CanvasTexture(canvas);
}

// 6-Axis Levitation Keyframes (matching CSS float6Axis)
const DEG2RAD = Math.PI / 180;
const KEYFRAMES = [
  { y: 0.00, rx: 10 * DEG2RAD, ry: -14 * DEG2RAD, rz: 2 * DEG2RAD },
  { y: 0.10, rx: 4 * DEG2RAD,  ry: 12 * DEG2RAD,  rz: -3 * DEG2RAD },
  { y: 0.20, rx: -8 * DEG2RAD, ry: 16 * DEG2RAD,  rz: 3 * DEG2RAD },
  { y: 0.10, rx: 2 * DEG2RAD,  ry: -8 * DEG2RAD,  rz: -2 * DEG2RAD }
];

function sampleKeyframe(normTime) {
  const p = ((normTime % 1) + 1) % 1;
  const scaled = p * 4;
  const idx = Math.floor(scaled);
  const frac = scaled - idx;
  const ease = (1 - Math.cos(frac * Math.PI)) / 2;
  const k1 = KEYFRAMES[idx % 4];
  const k2 = KEYFRAMES[(idx + 1) % 4];
  return {
    y: k1.y + (k2.y - k1.y) * ease,
    rx: k1.rx + (k2.rx - k1.rx) * ease,
    ry: k1.ry + (k2.ry - k1.ry) * ease,
    rz: k1.rz + (k2.rz - k1.rz) * ease
  };
}

// ------------------------------------------------------------
//  1. THREE.JS 3D STUDENT ID CARD MODEL (Fits Whole Box, Visible at All Angles)
// ------------------------------------------------------------
function initStudentIDCard() {
  const container = document.getElementById('hero-id-container');
  if (!container) return;
  container.innerHTML = '';

  const width = container.clientWidth || 335;
  const height = container.clientHeight || 510;

  const scene = new THREE.Scene();
  // Camera optimized so card fits cleanly with top clip and shadow
  const camera = new THREE.PerspectiveCamera(43, width / height, 0.1, 100);
  camera.position.set(0.4, 0.25, 5.3);

  const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true, powerPreference: 'high-performance' });
  renderer.setSize(width, height);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  renderer.setClearColor(0x000000, 0);
  renderer.domElement.style.outline = 'none';
  renderer.domElement.style.touchAction = 'none';
  container.appendChild(renderer.domElement);

  // Studio Lighting
  const ambientLight = new THREE.AmbientLight(0xffffff, 1.5);
  scene.add(ambientLight);

  const keyLight = new THREE.DirectionalLight(0xfffbf2, 2.0);
  keyLight.position.set(4, 7, 5);
  scene.add(keyLight);

  const rimLight = new THREE.DirectionalLight(0xede5d8, 1.2);
  rimLight.position.set(-5, 3, -4);
  scene.add(rimLight);

  // ID Card Group
  const idGroup = new THREE.Group();
  scene.add(idGroup);

  // ID Card Dimensions: Fits the whole box (2.60 x 3.97 x 0.05, Ratio = 1.527)
  const cardW = 2.60;
  const cardH = 3.97;
  const cardD = 0.05;

  // Load High-Resolution Cropped Student ID Image Texture
  const idImg = new Image();
  idImg.src = ID_CARD_BASE64;
  const idTexture = new THREE.Texture(idImg);
  if (idImg.complete) {
    idTexture.needsUpdate = true;
  }
  idImg.onload = () => {
    idTexture.needsUpdate = true;
  };
  idTexture.generateMipmaps = true;
  idTexture.minFilter = THREE.LinearFilter;
  idTexture.magFilter = THREE.LinearFilter;

  // Single Unified 3D Box Geometry: Image fits the whole front and back of the box!
  // No separate decals, no coplanar surfaces, no Z-fighting at any angle!
  const cardGeom = new THREE.BoxGeometry(cardW, cardH, cardD);

  // Front Material: DoubleSide & toneMapped false ensures full brightness & visibility at all angles
  const frontMat = new THREE.MeshBasicMaterial({
    map: idTexture,
    side: THREE.DoubleSide,
    toneMapped: false
  });

  // Back Material: DoubleSide ID texture so the image is visible from front, back, and all sides!
  const backMat = new THREE.MeshBasicMaterial({
    map: idTexture,
    side: THREE.DoubleSide,
    toneMapped: false
  });

  // Crisp White PVC Core Edge for the sides of the card
  const sideMat = new THREE.MeshStandardMaterial({
    color: 0xffffff,
    roughness: 0.4,
    metalness: 0.05
  });

  // Materials array for BoxGeometry: [+X, -X, +Y, -Y, +Z (front), -Z (back)]
  const materials = [sideMat, sideMat, sideMat, sideMat, frontMat, backMat];
  const cardMesh = new THREE.Mesh(cardGeom, materials);
  idGroup.add(cardMesh);

  // Chrome Metallic Badge Clip at Top (Positioned cleanly above the card so it never blocks the image)
  const clipGroup = new THREE.Group();
  clipGroup.position.set(0, cardH / 2 + 0.14, 0);

  const chromeMat = new THREE.MeshStandardMaterial({
    color: 0xdde3ea,
    metalness: 0.92,
    roughness: 0.16
  });

  const strapMesh = new THREE.Mesh(new THREE.BoxGeometry(0.44, 0.28, 0.07), chromeMat);
  clipGroup.add(strapMesh);

  const loopMesh = new THREE.Mesh(new THREE.TorusGeometry(0.14, 0.032, 12, 24), chromeMat);
  loopMesh.position.set(0, 0.15, 0);
  clipGroup.add(loopMesh);

  idGroup.add(clipGroup);

  // Soft Contact Floor Shadow
  const shadowTex = createShadowTexture();
  const shadowMat = new THREE.MeshBasicMaterial({
    map: shadowTex,
    transparent: true,
    opacity: 0.35,
    depthWrite: false
  });
  const shadowPlane = new THREE.Mesh(new THREE.PlaneGeometry(3.8, 2.6), shadowMat);
  shadowPlane.rotation.x = -Math.PI / 2;
  shadowPlane.position.y = -cardH / 2 - 0.45;
  scene.add(shadowPlane);

  // Interactive Orbit Controls (with fallback)
  let controls = null;
  let isInteracting = false;
  if (typeof THREE.OrbitControls !== 'undefined') {
    controls = new THREE.OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.dampingFactor = 0.06;
    controls.enableZoom = false;
    controls.enablePan = false;
    controls.minDistance = 3.0;
    controls.maxDistance = 8.5;
    controls.addEventListener('start', () => { isInteracting = true; });
    controls.addEventListener('end', () => { isInteracting = false; });
  } else {
    let isDown = false, px = 0, py = 0;
    renderer.domElement.addEventListener('mousedown', (e) => { isDown = true; isInteracting = true; px = e.clientX; py = e.clientY; });
    window.addEventListener('mousemove', (e) => {
      if (!isDown) return;
      const dx = e.clientX - px;
      const dy = e.clientY - py;
      idGroup.rotation.y += dx * 0.01;
      idGroup.rotation.x += dy * 0.01;
      px = e.clientX; py = e.clientY;
    });
    window.addEventListener('mouseup', () => { isDown = false; isInteracting = false; });
  }

  // Exact 6-Axis Levitation Animation (Starts at 0s, matching CSS float-6axis)
  const clock = new THREE.Clock();

  function animate() {
    requestAnimationFrame(animate);
    const t = clock.getElapsedTime();

    const normTime = t / 8.0;
    const kf = sampleKeyframe(normTime);

    const floatY = kf.y - 0.10;
    idGroup.position.y = floatY;

    if (!isInteracting) {
      idGroup.rotation.x = kf.rx;
      idGroup.rotation.y = kf.ry;
      idGroup.rotation.z = kf.rz;
    }

    // Pulsing Shadow
    if (shadowPlane) {
      const normY = (floatY + 0.10) / 0.20;
      shadowPlane.material.opacity = 0.35 - normY * 0.20;
      const s = 1.0 - normY * 0.30;
      shadowPlane.scale.set(s, s, s);
    }

    if (controls) controls.update();
    renderer.render(scene, camera);
  }
  animate();

  window.addEventListener('resize', () => {
    if (!container || container.clientWidth === 0) return;
    const w = container.clientWidth;
    const h = container.clientHeight;
    camera.aspect = w / h;
    camera.updateProjectionMatrix();
    renderer.setSize(w, h);
  });
}

// ------------------------------------------------------------
//  2. THREE.JS 3D LEATHER WALLET MODEL (Self-Contained)
// ------------------------------------------------------------
function initLeatherWallet() {
  const container = document.getElementById('hero-wallet-container');
  if (!container) return;
  container.innerHTML = '';

  const width = container.clientWidth || 315;
  const height = container.clientHeight || 385;

  const scene = new THREE.Scene();
  const camera = new THREE.PerspectiveCamera(34, width / height, 0.1, 100);
  camera.position.set(3.4, 2.3, 4.6);

  const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true, powerPreference: 'high-performance' });
  renderer.setSize(width, height);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  renderer.setClearColor(0x000000, 0);
  renderer.domElement.style.outline = 'none';
  renderer.domElement.style.touchAction = 'none';
  container.appendChild(renderer.domElement);

  // Studio Lighting
  const ambientLight = new THREE.AmbientLight(0xfff5e8, 1.4);
  scene.add(ambientLight);

  const keyLight = new THREE.DirectionalLight(0xfffbf2, 2.5);
  keyLight.position.set(5, 8, 6);
  scene.add(keyLight);

  const rimLight = new THREE.DirectionalLight(0xede5d8, 1.5);
  rimLight.position.set(-6, 4, -5);
  scene.add(rimLight);

  const bottomFill = new THREE.DirectionalLight(0xe4d7c5, 0.85);
  bottomFill.position.set(0, -5, 2);
  scene.add(bottomFill);

  // Procedural Pebbled Leather Bump Map
  function createLeatherBump() {
    const canvas = document.createElement('canvas');
    canvas.width = 512;
    canvas.height = 512;
    const ctx = canvas.getContext('2d');
    ctx.fillStyle = '#808080';
    ctx.fillRect(0, 0, 512, 512);

    for (let i = 0; i < 28000; i++) {
      const x = Math.random() * 512;
      const y = Math.random() * 512;
      const r = Math.random() * 1.4 + 0.4;
      const shade = Math.floor(115 + Math.random() * 25);
      ctx.fillStyle = 'rgb(' + shade + ',' + shade + ',' + shade + ')';
      ctx.beginPath();
      ctx.arc(x, y, r, 0, Math.PI * 2);
      ctx.fill();
    }
    const texture = new THREE.CanvasTexture(canvas);
    texture.wrapS = THREE.RepeatWrapping;
    texture.wrapT = THREE.RepeatWrapping;
    texture.repeat.set(3, 3);
    return texture;
  }

  const leatherBump = createLeatherBump();

  // Materials
  const outerLeatherMat = new THREE.MeshStandardMaterial({
    color: 0x3b2316,
    roughness: 0.42,
    metalness: 0.04,
    bumpMap: leatherBump,
    bumpScale: 0.008
  });

  const innerLeatherMat = new THREE.MeshStandardMaterial({
    color: 0x4f301f,
    roughness: 0.55,
    bumpMap: leatherBump,
    bumpScale: 0.012
  });

  const stitchMat = new THREE.MeshStandardMaterial({
    color: 0xede5d8,
    roughness: 0.4
  });

  const brassMat = new THREE.MeshStandardMaterial({
    color: 0xd4af37,
    metalness: 0.88,
    roughness: 0.22
  });

  // Wallet Group
  const walletGroup = new THREE.Group();
  scene.add(walletGroup);

  const wWidth = 2.6;
  const wHeight = 1.8;
  const flapRadius = 0.14;

  // Front & Back Leather Flaps
  const frontFlap = new THREE.Mesh(createRoundedBox(wWidth, wHeight, 0.16, flapRadius, 0.012), outerLeatherMat);
  frontFlap.position.set(0.08, 0, 0.14);
  walletGroup.add(frontFlap);

  const backFlap = new THREE.Mesh(createRoundedBox(wWidth, wHeight, 0.16, flapRadius, 0.012), outerLeatherMat);
  backFlap.position.set(0.08, 0, -0.14);
  walletGroup.add(backFlap);

  // Curved Bifold Spine
  const spineGeo = new THREE.CylinderGeometry(0.23, 0.23, wHeight - 0.06, 36, 1, false, Math.PI, Math.PI);
  const spineMesh = new THREE.Mesh(spineGeo, outerLeatherMat);
  spineMesh.position.set(-wWidth / 2 + 0.12, 0, 0);
  walletGroup.add(spineMesh);

  // Spine Spherical Caps
  const capGeo = new THREE.SphereGeometry(0.228, 24, 24);
  capGeo.scale(1, 0.35, 1);
  const topCap = new THREE.Mesh(capGeo, outerLeatherMat);
  topCap.position.set(-wWidth / 2 + 0.12, (wHeight - 0.08) / 2, 0);
  walletGroup.add(topCap);

  const bottomCap = topCap.clone();
  bottomCap.position.y = -(wHeight - 0.08) / 2;
  walletGroup.add(bottomCap);

  // Inner Divider
  const innerDivider = new THREE.Mesh(createRoundedBox(wWidth - 0.12, wHeight - 0.12, 0.08, 0.08, 0.008), innerLeatherMat);
  innerDivider.position.set(0.06, 0, 0);
  walletGroup.add(innerDivider);

  // Clasp Strap & Brass Button
  const strapMesh = new THREE.Mesh(createRoundedBox(0.65, 0.42, 0.24, 0.10, 0.01), outerLeatherMat);
  strapMesh.position.set(wWidth / 2 - 0.1, 0, 0.07);
  walletGroup.add(strapMesh);

  const buttonGeo = new THREE.CylinderGeometry(0.10, 0.10, 0.06, 24);
  buttonGeo.rotateX(Math.PI / 2);
  const brassButton = new THREE.Mesh(buttonGeo, brassMat);
  brassButton.position.set(wWidth / 2 - 0.18, 0, 0.20);
  walletGroup.add(brassButton);

  // Contrast Saddle Stitching
  const stitchGeo = new THREE.CylinderGeometry(0.012, 0.012, 0.05, 8);
  stitchGeo.rotateZ(Math.PI / 2);

  function addStitchRow(startX, startY, endX, endY, count, zPos, isVert = false) {
    for (let i = 0; i <= count; i++) {
      const t = i / count;
      const stitch = new THREE.Mesh(stitchGeo, stitchMat);
      stitch.position.set(
        startX + (endX - startX) * t,
        startY + (endY - startY) * t,
        zPos
      );
      if (isVert) stitch.rotation.z = Math.PI / 2;
      walletGroup.add(stitch);
    }
  }

  const sZ = 0.23;
  addStitchRow(-1.0, 0.74, 1.15, 0.74, 18, sZ, false);
  addStitchRow(-1.0, -0.74, 1.15, -0.74, 18, sZ, false);
  addStitchRow(1.18, -0.66, 1.18, 0.66, 12, sZ, true);

  // Peeking ID Card (Blue) & Credit Card (Gold)
  const idCardMat = new THREE.MeshStandardMaterial({ color: 0x38bdf8, roughness: 0.2, metalness: 0.1 });
  const goldCardMat = new THREE.MeshStandardMaterial({ color: 0xeab308, roughness: 0.25, metalness: 0.6 });

  const cardGeo = createRoundedBox(1.9, 1.15, 0.03, 0.06, 0.005);
  const idCard = new THREE.Mesh(cardGeo, idCardMat);
  idCard.position.set(-0.08, 0.46, 0.05);
  idCard.rotation.z = 0.03;
  walletGroup.add(idCard);

  const goldCard = new THREE.Mesh(cardGeo, goldCardMat);
  goldCard.position.set(0.18, 0.54, -0.04);
  goldCard.rotation.z = -0.04;
  walletGroup.add(goldCard);

  // Floor Contact Shadow
  const shadowTex = createShadowTexture();
  const shadowMat = new THREE.MeshBasicMaterial({
    map: shadowTex,
    transparent: true,
    opacity: 0.35,
    depthWrite: false
  });
  const shadowPlane = new THREE.Mesh(new THREE.PlaneGeometry(3.6, 2.4), shadowMat);
  shadowPlane.rotation.x = -Math.PI / 2;
  shadowPlane.position.y = -1.35;
  scene.add(shadowPlane);

  // Interactive Orbit Controls (with fallback)
  let controls = null;
  let isInteracting = false;
  if (typeof THREE.OrbitControls !== 'undefined') {
    controls = new THREE.OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.dampingFactor = 0.06;
    controls.enableZoom = false;
    controls.enablePan = false;
    controls.minDistance = 3.5;
    controls.maxDistance = 9;
    controls.addEventListener('start', () => { isInteracting = true; });
    controls.addEventListener('end', () => { isInteracting = false; });
  } else {
    let isDown = false, px = 0, py = 0;
    renderer.domElement.addEventListener('mousedown', (e) => { isDown = true; isInteracting = true; px = e.clientX; py = e.clientY; });
    window.addEventListener('mousemove', (e) => {
      if (!isDown) return;
      const dx = e.clientX - px;
      const dy = e.clientY - py;
      walletGroup.rotation.y += dx * 0.01;
      walletGroup.rotation.x += dy * 0.01;
      px = e.clientX; py = e.clientY;
    });
    window.addEventListener('mouseup', () => { isDown = false; isInteracting = false; });
  }

  // Animation Loop (float-6axis-offset: 3s offset)
  const clock = new THREE.Clock();

  function animate() {
    requestAnimationFrame(animate);
    const t = clock.getElapsedTime();

    const normTime = (t + 3.0) / 8.0;
    const kf = sampleKeyframe(normTime);

    const floatY = kf.y - 0.10;
    walletGroup.position.y = floatY;

    if (!isInteracting) {
      walletGroup.rotation.x = kf.rx;
      walletGroup.rotation.y = kf.ry;
      walletGroup.rotation.z = kf.rz;
    }

    // Pulsing Shadow
    if (shadowPlane) {
      const normY = (floatY + 0.10) / 0.20;
      shadowPlane.material.opacity = 0.35 - normY * 0.20;
      const s = 1.0 - normY * 0.30;
      shadowPlane.scale.set(s, s, s);
    }

    if (controls) controls.update();
    renderer.render(scene, camera);
  }
  animate();

  window.addEventListener('resize', () => {
    if (!container || container.clientWidth === 0) return;
    const w = container.clientWidth;
    const h = container.clientHeight;
    camera.aspect = w / h;
    camera.updateProjectionMatrix();
    renderer.setSize(w, h);
  });
}

// ------------------------------------------------------------
//  INITIALIZE SHOWCASE WHEN DOM & THREE ARE READY
// ------------------------------------------------------------
function startShowcase() {
  if (typeof THREE === 'undefined') {
    setTimeout(startShowcase, 80);
    return;
  }
  initStudentIDCard();
  initLeatherWallet();
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', startShowcase);
} else {
  startShowcase();
}
